import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Research","description":"","frontmatter":{"source":"research/README.md"},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md"}'),s={name:"research/index.md"};function n(i,e,d,h,c,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h1><blockquote><p>The evidence behind Engineering Software with AI: what comparable courses do, what the research shows, and what the free tools offer. Start with the report; go to the notes for sources and detail.</p></blockquote><table tabindex="0"><thead><tr><th>File</th><th>What it is</th><th>Read it if</th></tr></thead><tbody><tr><td><a href="./landscape-report-2026-11.html">Landscape Report: Teaching Agentic Software Engineering to Seniors and Graduate Students</a></td><td>A synthesis of the three notes, with a summary up front and every claim linked to its source</td><td>You want the case for the course&#39;s design in one sitting</td></tr><tr><td><a href="./design-rationale.html">Why the Course Looks Like This</a></td><td>A table of the main design decisions, the evidence for each, and where each appears in the course</td><td>You&#39;re adapting the course, reviewing it, or wondering why it asks you to work a certain way</td></tr><tr><td><a href="./notes/courses-upper-division.html">Upper-Division, Graduate, and Semester-Length AI-Assisted SE Courses: Research for the Course A / Course B Split</a></td><td>Comparable upper-division and graduate courses (UT Austin, Michigan, CMU, Stanford, UMD, UVA, ANU, Cornell, CU Boulder), team projects on open-source codebases, and how joint-listed courses differentiate graduate credit</td><td>You want the course details behind a decision</td></tr><tr><td><a href="./notes/tools-senior.html">Course B (&quot;Engineering Software with AI&quot;): the $0 tool landscape, checked 2 November 2026</a></td><td>The $0 tool landscape checked on 2026-11-02, with the recommended stack, risks and unverified items</td><td>You&#39;re updating <a href="./../TOOLS.html">Tool Handout</a></td></tr><tr><td><a href="./notes/evidence-senior.html">Evidence Base and Reading List: &quot;Engineering Software with AI&quot; (CS 4xxx/5xxx)</a></td><td>An annotated bibliography: productivity, benchmarks, verification, review, security, evals, skills and open-source norms, with [Grad seminar] and [Replicable] tags</td><td>You&#39;re choosing a reading, a presentation paper or a study</td></tr></tbody></table><h2 id="how-to-read-the-sources" tabindex="-1">How to read the sources <a class="header-anchor" href="#how-to-read-the-sources" aria-label="Permalink to &quot;How to read the sources&quot;">​</a></h2><p>The notes label every item by kind, so you can weigh it:</p><ul><li><strong>[PR]</strong> peer-reviewed or accepted · <strong>[Pre]</strong> preprint · <strong>[Ind-R]</strong> industry research · <strong>[Vendor]</strong> a company writing about its own product or market · <strong>[Docs]</strong> official documentation · <strong>[News]</strong> press coverage · <strong>[Pract]</strong> practitioner writing · <strong>[Legal]</strong> court records and legal coverage.</li><li>In the tool notes: <strong>[official]</strong> the vendor&#39;s own page · <strong>[3rd]</strong> a third party · <strong>[snippet]</strong> seen only in a search summary · <strong>[GH]</strong> read from the GitHub API or a package registry · <strong>[A]</strong> carried over from the sibling course&#39;s notes without re-checking · <strong>UNVERIFIED</strong> could not be confirmed.</li><li>&quot;Search summary&quot; and &quot;coverage&quot; mean the course didn&#39;t read the primary source; numbers from them are flagged where they&#39;re used.</li></ul><h2 id="dates-and-the-two-layer-rule" tabindex="-1">Dates and the two-layer rule <a class="header-anchor" href="#dates-and-the-two-layer-rule" aria-label="Permalink to &quot;Dates and the two-layer rule&quot;">​</a></h2><p>Research files are <strong>dated records</strong>: they describe what was true when they were written, so they may name models, prices and the dates of tool changes. The rest of the course keeps those facts in <a href="./../TOOLS.html">Tool Handout</a> only, so that a product change means editing one file. When a fact here goes stale, don&#39;t edit the old note: add a new dated note, update TOOLS.md, and update the report or rationale if a decision changes.</p><h2 id="relationship-to-the-sibling-course" tabindex="-1">Relationship to the sibling course <a class="header-anchor" href="#relationship-to-the-sibling-course" aria-label="Permalink to &quot;Relationship to the sibling course&quot;">​</a></h2><p>The lower-division course, Building Apps with AI, has its own research reports (September and October 2026). These notes cover what is new or different for seniors and graduate students; where they rely on the sibling&#39;s findings (some incidents, the Safe Loop, some 2025–26 studies), they say so, and the course&#39;s <a href="./../resources/case-studies.html">case studies</a> mark those items <strong>[A]</strong>.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>Found a newer study, a course that published outcome data, or a tool change? Open an <a href="https://github.com/Boyu-Zhang-UOI/engineering-software-with-ai/issues/new/choose" target="_blank" rel="noreferrer">erratum</a> or <a href="https://github.com/Boyu-Zhang-UOI/engineering-software-with-ai/issues/new/choose" target="_blank" rel="noreferrer">tool change</a> issue with the source. The gaps the course most wants filled are listed in the report&#39;s <a href="./landscape-report-2026-11.html#7-gaps">gaps section</a>.</p>',12)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
